// Per column frame: whether Chzzk's follow, subscribe and gift-subscription buttons are on screen and on top
// (the frame CSS once hid <main>'s whole channel row), the player box ratio (must stay 16:9), and whether the
// ambient canvas still shows (a more specific hide rule once beat its display rule).
(() => {
  const box = (e) => (e ? [e.getBoundingClientRect()].map((r) => [r.x, r.y, r.width, r.height].map(Math.round))[0] : null);
  return JSON.stringify([...document.querySelectorAll(".cb-split-body > iframe")].map((f) => {
    const d = f.contentDocument, w = f.contentWindow;
    const hit = (re) => {
      const b = [...d.querySelectorAll("#layout-body main button")].find((b) => re.test(b.innerText));
      if (!b) return "missing";
      const r = b.getBoundingClientRect(), e = d.elementFromPoint(r.x + r.width / 2, r.y + r.height / 2);
      return r.width > 0 && r.top >= 0 && r.bottom <= w.innerHeight && !!e && b.contains(e);
    };
    const p = box(d.querySelector("#layout-body main > :first-child > :first-child")), c = d.querySelector("#layout-body main > canvas.cb-ambient");
    return {
      col: f.dataset.cbCol.slice(0, 8), frame: [w.innerWidth, w.innerHeight], player: p, ratio: p && +(p[2] / p[3]).toFixed(2),
      details: box(d.querySelector('#layout-body main > [class*="_details_"]')), aside: box(d.querySelector("#aside-chatting")),
      follow: hit(/^팔로우|^언팔로우/), subscribe: hit(/^구독$|^구독 중|^구독하기/), gift: hit(/구독 선물/),
      ambient: c ? getComputedStyle(c).display : null,
    };
  }));
})()

